import csv, statistics
from collections import defaultdict
cat=list(csv.DictReader(open(CATALOG_CSV)))
damper={r['point_uri'].split('#')[1]:r['timeseries_id'] for r in cat if r['point_class']=='Damper_Position_Setpoint' and r['point_uri'].endswith('.Damper_Position_Setpoint')}
damper={k:v for k,v in damper.items() if '_Z01' in k or '_Z02' in k}
vals=defaultdict(dict)
for r in csv.DictReader(open(VALUES_CSV)):
    vals[r['timeseries_id']].setdefault(r['timestamp'][:7], []).append(float(r['value']))
hdr='month     '
for z in sorted(damper): hdr+=z.split('.')[0].ljust(14)
print(hdr)
for m in ['2018-03','2018-06','2018-09','2018-12']:
    line=m.ljust(10)
    for z in sorted(damper):
        line+=str(round(statistics.mean(vals[damper[z]].get(m,[0])),3)).ljust(14)
    print(line)
print(sorted(damper))

